<script setup lang="ts">
import {computed,nextTick,reactive,ref,watch} from 'vue'
export interface QuerySnapshot {dataset:string;mode:string;window:string;filter:string;terms:Record<string,string>}
interface Entry {id:string;revision:number;name:string;description:string;visibility:string;active:boolean;snapshot:QuerySnapshot}
const props=defineProps<{snapshot:QuerySnapshot;createOpen?:boolean}>(),emit=defineEmits<{apply:[value:QuerySnapshot];close:[]}>()
const entries=ref<Entry[]>([]),library=ref(false),editing=ref(false),selected=ref<Entry>(),detail=ref<Entry>(),error=ref(''),errorElement=ref<HTMLDivElement>()
const fields=reactive({name:'',description:'',visibility:'personal',active:true,replace:false}),keyword=ref(''),visibility=ref(''),active=ref('true')
const listing=computed(()=>entries.value.filter(row=>row.snapshot.dataset===props.snapshot.dataset&&(!keyword.value||row.name.includes(keyword.value))&&(!visibility.value||row.visibility===visibility.value)&&(!active.value||row.active===(active.value==='true'))))
const copy=(value:QuerySnapshot):QuerySnapshot=>({...value,terms:{...value.terms}})
const definition=computed(()=>copy(selected.value&&!fields.replace?selected.value.snapshot:props.snapshot))
function open(record?:Entry){library.value=false;detail.value=undefined;selected.value=record;Object.assign(fields,{name:record?.name??'',description:record?.description??'',visibility:record?.visibility??'personal',active:record?.active??true,replace:false});error.value='';editing.value=true}
function close(){editing.value=false;emit('close')}
function save(){
 const name=fields.name.trim(),description=fields.description.trim()
 error.value=!name?'请填写查询名称。':Array.from(name).length>128||Array.from(description).length>1000||/[\p{Cc}]/u.test(name+description)?'名称和用途说明超出长度限制或含控制字符。':''
 if(error.value){void nextTick(()=>errorElement.value?.focus());return}
 const record=selected.value,next:Entry={id:record?.id??crypto.randomUUID(),revision:(record?.revision??0)+1,name,description,visibility:fields.visibility,active:fields.active,snapshot:definition.value}
 if(record)entries.value=entries.value.map(row=>row.id===record.id?next:row);else entries.value.push(next)
 close()
}
function apply(record:Entry){if(!record.active)return;emit('apply',copy(record.snapshot));library.value=false;detail.value=undefined}
watch(()=>props.createOpen,value=>{if(value)open()},{immediate:true})
</script>
<template>
 <a-space><a-button @click="open()">保存当前查询</a-button><a-button @click="library=true">已保存查询</a-button></a-space>
 <a-modal :open="library" title="已保存查询" :width="820" :footer="null" :mask-closable="false" @cancel="library=false"><a-alert message="当前为合成示例，查询仅保存在浏览器内存；团队共享只共享条件，不授予数据权限。" type="info" show-icon/><div class="saved-prototype-filters"><label>查询名称<a-input v-model:value="keyword" :maxlength="128" allow-clear/></label><label>可见范围<a-select v-model:value="visibility" :options="[{label:'全部可见查询',value:''},{label:'仅自己',value:'personal'},{label:'团队共享',value:'team'}]"/></label><label>查询状态<a-select v-model:value="active" :options="[{label:'启用',value:'true'},{label:'停用',value:'false'},{label:'全部状态',value:''}]"/></label></div><a-empty v-if="!listing.length" description="当前条件下没有保存查询。完成检索后可保存常用条件。"/><ul v-else class="saved-prototype-list"><li v-for="record in listing" :key="record.id"><div><strong>{{record.name}}</strong><p>{{record.visibility==='personal'?'仅自己':'团队共享'}} · {{record.active?'启用':'停用'}} · {{record.snapshot.window}} · 修订 {{record.revision}}</p><small>{{record.description}}</small></div><a-space wrap><a-button size="small" @click="library=false;detail=record">查看</a-button><a-button size="small" type="primary" :disabled="!record.active" @click="apply(record)">应用</a-button><a-button size="small" @click="open(record)">编辑</a-button></a-space></li></ul></a-modal>
 <a-modal :open="editing" :title="selected?'编辑保存查询':'保存当前查询'" :width="680" :footer="null" :mask-closable="false" @cancel="close"><a-alert message="保存条件和时间窗口。相对窗口在每次应用时重新计算，固定窗口保持原起止时间。" type="info" show-icon/><div v-if="error" ref="errorElement" tabindex="-1" role="alert" class="saved-prototype-error"><a-alert :message="error" type="error" show-icon/></div><a-form :model="fields" layout="vertical" @finish="save"><a-form-item label="查询名称" html-for="prototype-saved-name" required><a-input id="prototype-saved-name" v-model:value="fields.name" :maxlength="128"/></a-form-item><a-form-item label="用途说明" html-for="prototype-saved-description"><a-input id="prototype-saved-description" v-model:value="fields.description" :maxlength="1000"/></a-form-item><div class="saved-prototype-filters"><a-form-item label="可见范围"><a-select v-model:value="fields.visibility" :options="[{label:'仅自己',value:'personal'},{label:'团队共享',value:'team'}]"/></a-form-item><a-form-item v-if="selected" label="查询状态"><a-switch v-model:checked="fields.active" checked-children="启用" un-checked-children="停用"/></a-form-item></div><a-checkbox v-if="selected" v-model:checked="fields.replace">使用当前页面的查询条件和时间窗口</a-checkbox><pre class="saved-prototype-definition">{{JSON.stringify(definition,null,2)}}</pre><div class="saved-prototype-actions"><a-button @click="close">关闭</a-button><a-button type="primary" html-type="submit">保存</a-button></div></a-form></a-modal>
 <a-modal :open="!!detail" :title="detail?.name" :width="720" :footer="null" @cancel="detail=undefined"><template v-if="detail"><p>{{detail.description||'未填写用途说明'}}</p><pre class="saved-prototype-definition">{{JSON.stringify(detail.snapshot,null,2)}}</pre><a-alert v-if="!detail.active" message="该查询已停用，不能应用。" type="warning" show-icon/><div class="saved-prototype-actions"><a-button @click="detail=undefined;library=true">返回列表</a-button><a-button type="primary" :disabled="!detail.active" @click="apply(detail)">应用查询</a-button></div></template></a-modal>
</template>
<style scoped>.saved-prototype-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:12px 0}.saved-prototype-filters label{display:grid;gap:6px}.saved-prototype-list{list-style:none;padding:0}.saved-prototype-list li{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid var(--border-color)}.saved-prototype-list li>div{min-width:0;overflow-wrap:anywhere}.saved-prototype-list p{margin:4px 0}.saved-prototype-definition{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--surface-subtle,#f7f8fa);color:var(--text-primary,#1f2937);border:1px solid var(--border-color,#d9e0e8);border-radius:6px;padding:12px}.saved-prototype-actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap;margin-top:12px}.saved-prototype-error{margin:12px 0}</style>
